import test from 'node:test';
import assert from 'node:assert/strict';
let sequence=0;
async function fixture({stored=null,storageError=false,referrer='https://www.google.com/search?q=private@example.test',appendError=false}={}) {
 const scripts=[],listeners=new Map(),jar=new Map([['_ga','fixture'],['_ga_WJ6METJRZD','fixture'],['necessary','keep']]);
 const store=new Map(stored?[['pyp.analytics-consent.v1',JSON.stringify(stored)]]:[]);
 globalThis.window={location:{href:'https://pyptecnologia.com/?correo=private@example.test#private',origin:'https://pyptecnologia.com',hostname:'pyptecnologia.com'},localStorage:{getItem:k=>{if(storageError)throw Error('blocked');return store.get(k)||null;},setItem:(k,v)=>{if(storageError)throw Error('blocked');store.set(k,v);}},addEventListener:(n,fn)=>listeners.set(n,fn)};
 globalThis.document={referrer,head:{appendChild:s=>{if(appendError)throw Error('CSP');scripts.push(s);}},createElement:()=>({remove(){this.removed=true;}}),get cookie(){return [...jar].map(([k,v])=>k+'='+v).join('; ');},set cookie(v){if(v.includes('Max-Age=0'))jar.delete(v.split('=')[0]);}};
 const api=await import('../../../src/lib/analytics.js?case='+sequence++);
 const calls=()=>[...(window.dataLayer||[])].map(x=>Array.from(x));
 const events=()=>calls().filter(c=>c[0]==='event');
 const views=()=>events().filter(c=>c[1]==='page_view');
 return {api,scripts,listeners,store,jar,calls,events,views,load(){scripts.at(-1).onload();}};
}
const granted=()=>({value:'granted',expires:Date.now()+86400000});
test('SSR: importing/starting analytics never accesses window',async()=>{delete globalThis.window;delete globalThis.document;const a=await import('../../../src/lib/analytics.js?ssr');assert.doesNotThrow(()=>{a.startAnalytics();a.recordPage('/');a.setConsent('granted');});});
test('Unknown and denied: zero tag, cookies, commands; no pre-consent replay',async()=>{const f=await fixture();f.api.startAnalytics();f.api.recordPage('/');f.api.recordPage('/proyectos/clg/');assert.equal(f.scripts.length,0);assert.equal(f.events().length,0);f.api.setConsent('denied');assert.equal(f.scripts.length,0);f.api.setConsent('granted');f.load();assert.equal(f.views().length,1);assert.equal(f.views()[0][2].page_location,'https://pyptecnologia.com/proyectos/clg/');});
test('One config/tag, correct ID, no automatic page_view, ad personalization disabled',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.startAnalytics();f.api.recordPage('/');f.load();f.api.recordPage('/');f.api.setConsent('granted');assert.equal(f.scripts.length,1);assert.equal(f.scripts[0].src,'https://www.googletagmanager.com/gtag/js?id=G-WJ6METJRZD');assert.equal(f.scripts[0].referrerPolicy,'no-referrer');const c=f.calls().filter(c=>c[0]==='config');assert.equal(c.length,1);assert.equal(c[0][1],f.api.MEASUREMENT_ID);assert.equal(c[0][2].send_page_view,false);assert.equal(c[0][2].allow_google_signals,false);assert.equal(c[0][2].allow_ad_personalization_signals,false);assert.equal(f.views().length,1);});
test('All five routes, title/canonical, repeat effects, slash/query/hash, return visits',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/');f.load();for(const r of ['/monitoreo-energetico','/iot-industrial','/automatizacion-edge','/proyectos/clg']){f.api.recordPage(r);f.api.recordPage(r+'/','?nombre=private');}assert.equal(f.views().length,5);const clg=f.views().at(-1)[2];assert.equal(clg.page_location,'https://pyptecnologia.com/proyectos/clg/');assert.equal(clg.page_title,'CLG | Audio Inteligente y Automatización IoT | PYP');assert.equal(clg.page_referrer,'https://pyptecnologia.com/automatizacion-edge/');f.api.recordPage('/');assert.equal(f.views().length,6);});
test('Slow tag: first view is current route, no navigation replay',async()=>{const f=await fixture();f.api.startAnalytics();f.api.recordPage('/');f.api.setConsent('granted');f.api.recordPage('/iot-industrial');f.api.recordPage('/proyectos/clg');f.load();assert.equal(f.views().length,1);assert.equal(f.views()[0][2].page_path,'/proyectos/clg/');});
test('Revoke mid-load then accept: no event while denied, one initialization',async()=>{const f=await fixture();f.api.startAnalytics();f.api.recordPage('/');f.api.setConsent('granted');f.api.setConsent('denied');f.load();assert.equal(f.events().length,0);f.api.setConsent('granted');assert.equal(f.views().length,1);assert.equal(f.calls().filter(c=>c[0]==='config').length,1);});
test('Revoke after load: opt-out flag, remove only GA cookies, no events, accept current page',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/');f.load();f.api.setConsent('denied');assert.equal(window['ga-disable-G-WJ6METJRZD'],true);assert(!f.jar.has('_ga'));assert(!f.jar.has('_ga_WJ6METJRZD'));assert(f.jar.has('necessary'));f.api.recordPage('/proyectos/clg');assert.equal(f.events().length,0);f.api.setConsent('granted');assert.equal(window['ga-disable-G-WJ6METJRZD'],false);assert.equal(f.views().length,1);assert.equal(f.views()[0][2].page_path,'/proyectos/clg/');assert.equal(f.scripts.length,1);});
test('Cross-tab revoke/storage deletion and expired/invalid choices default to no collection',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/');f.load();f.store.clear();f.listeners.get('storage')({key:null});assert.equal(f.api.getConsent(),'unknown');assert.equal(window['ga-disable-G-WJ6METJRZD'],true);for(const stored of [{value:'granted',expires:1},{value:'granted',expires:Date.now()+999999999999},{value:'other',expires:Date.now()+1000}]){const g=await fixture({stored});g.api.startAnalytics();assert.equal(g.api.getConsent(),'unknown');assert.equal(g.scripts.length,0);}});
test('Unavailable localStorage: can reject/accept within this tab without throwing',async()=>{const f=await fixture({storageError:true});f.api.startAnalytics();assert.equal(f.api.getConsent(),'unknown');f.api.recordPage('/');f.api.setConsent('denied');f.api.setConsent('granted');f.load();assert.equal(f.views().length,1);});
test('Tag blocked/CSP, failed/retry and throwing gtag cannot break navigation',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/');f.scripts[0].onerror();assert.equal(f.events().length,0);assert.doesNotThrow(()=>f.api.recordPage('/proyectos/clg'));f.api.setConsent('granted');f.load();window.gtag=()=>{throw Error('blocked');};assert.doesNotThrow(()=>f.api.recordPage('/'));const g=await fixture({stored:granted(),appendError:true});assert.doesNotThrow(()=>{g.api.startAnalytics();g.api.recordPage('/');});});
test('UTM allowlist: sanitized campaign tokens only; canonical excludes query/hash and referrer path',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/proyectos/clg','?utm_source=linkedin&utm_medium=social&utm_campaign=clg_oct_2026&utm_content=ficha&utm_term=private@example.test&correo=private@example.test&gclid=private');f.load();const config=f.calls().find(c=>c[0]==='config')[2];assert.equal(config.campaign_source,'linkedin');assert.equal(config.campaign_name,'clg_oct_2026');assert.equal(config.campaign_content,'ficha');assert.equal(config.page_referrer,'https://www.google.com/');assert(!JSON.stringify(f.calls()).includes('private'));});
test('Invalid UTM values are discarded',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/','?utm_source=private%40example.test&utm_medium=%2B573204929150&utm_campaign=person%20name&utm_content=123456789');f.load();const c=f.calls().find(c=>c[0]==='config')[2];assert(!Object.keys(c).some(k=>k.startsWith('campaign_')));});
const click=href=>({button:0,target:{closest:()=>({getAttribute:()=>href})}});
test('Contact clicks email/phone/WhatsApp and CLG CTA: allowlisted fields, duplicate event suppressed',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/proyectos/clg');f.load();for(const href of ['mailto:private@example.test?subject=private','tel:+573204929150','https://wa.me/573204929150?text=private','/#contacto']){const event=click(href);f.api.recordContactClick(event);f.api.recordContactClick(event);}const clicks=f.events().filter(c=>c[1]!=='page_view');assert.equal(clicks.length,4);assert.deepEqual(clicks.map(c=>c[1]),['contact_click','contact_click','contact_click','contact_cta_click']);assert.deepEqual(clicks.slice(0,3).map(c=>c[2].contact_method),['email','phone','whatsapp']);assert(clicks.every(c=>c[2].page_path==='/proyectos/clg/'));assert(!JSON.stringify(clicks).includes('private'));assert(!JSON.stringify(clicks).includes('573204929150'));f.api.recordContactClick(click('https://example.com'));assert.equal(f.events().length,5);});
test('Rejected/no tag: contact clicks and form interactions never emit generate_lead',async()=>{const f=await fixture();f.api.startAnalytics();f.api.recordPage('/');f.api.recordContactClick(click('mailto:private@example.test'));assert.equal(f.events().length,0);f.api.setConsent('granted');f.load();const before=f.events().length;for(const target of ['button[type=submit]','input','form'])f.api.recordContactClick({target:{closest:()=>null},button:0});assert.equal(f.events().length,before);assert(!f.events().some(c=>c[1]==='generate_lead'));assert(!('generateLead' in f.api));});

test('BFCache restore: one new view, no new tag/config; ordinary pageshow does not duplicate',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/');f.load();assert.equal(typeof f.listeners.get('pageshow'),'function');f.listeners.get('pageshow')({persisted:false});assert.equal(f.views().length,1);f.listeners.get('pageshow')({persisted:true});assert.equal(f.views().length,2);assert.equal(f.scripts.length,1);assert.equal(f.calls().filter(c=>c[0]==='config').length,1);});
test('BFCache restore rereads revoked/expired consent and stops collection',async()=>{const f=await fixture({stored:granted()});f.api.startAnalytics();f.api.recordPage('/');f.load();f.store.set(f.api.CONSENT_KEY,JSON.stringify({value:'denied',expires:Date.now()+86400000}));assert.equal(typeof f.listeners.get('pageshow'),'function');f.listeners.get('pageshow')({persisted:true});assert.equal(f.api.getConsent(),'denied');assert.equal(window['ga-disable-G-WJ6METJRZD'],true);assert.equal(f.views().length,0);assert(!f.jar.has('_ga'));f.store.set(f.api.CONSENT_KEY,JSON.stringify({value:'granted',expires:1}));f.listeners.get('pageshow')({persisted:true});assert.equal(f.api.getConsent(),'unknown');assert.equal(f.views().length,0);});
test('BFCache restore can read consent granted in another document without replay',async()=>{const f=await fixture({stored:{value:'denied',expires:Date.now()+86400000}});f.api.startAnalytics();f.api.recordPage('/proyectos/rpi-mdfr/');assert.equal(f.scripts.length,0);f.store.set(f.api.CONSENT_KEY,JSON.stringify(granted()));assert.equal(typeof f.listeners.get('pageshow'),'function');f.listeners.get('pageshow')({persisted:true});f.load();assert.equal(f.views().length,1);assert.equal(f.views()[0][2].page_path,'/proyectos/rpi-mdfr/');assert.equal(f.calls().filter(c=>c[0]==='config').length,1);});

import fs from 'node:fs';
import assert from 'node:assert/strict';
const base='docs/evidencias/PYP-035';
const read=name=>JSON.parse(fs.readFileSync(base+'/'+name,'utf8'));
const baseline=read('diagnostico-runtime-transporte204.json'),uiBefore=read('diagnostico-runtime-interfaz204-v2.json'),uiAfter=read('diagnostico-runtime-interfaz-corregida.json'),control=read('diagnostico-runtime-control-corregido.json');
const checks=[];
const check=(name,fn)=>{try{fn();checks.push({name,ok:true});}catch(e){checks.push({name,ok:false,error:e.message});}};
const step=(d,name,run='classified')=>d.steps.find(s=>s.name===name&&s.run===run);
for(const [name,d]of Object.entries({baseline,uiBefore,uiAfter,control})){
 check(name+' recorrido completo sin excepciones',()=>{assert.equal(d.completed,true);assert.equal(d.exceptions.length,0);});
 check(name+' sin consentimiento/rechazo: cero carga, vistas y cookies',()=>{for(const name of ['unknown-home','denied-home']){const s=step(d,name);assert.equal(s.publicViews,0);assert.equal(s.networkViews.length,0);assert.equal(s.tagLoads,0);assert.equal(s.state.gaCookieCount,0);}});
 check(name+' revocación y retorno: cero recopilación/cookies',()=>{for(const s of d.steps.filter(s=>s.name==='revoke-clg'||s.name.includes('after-revoke'))){assert.equal(s.publicViews,0);assert.equal(s.networkViews.length,0);assert.equal(s.state.gaCookieCount,0);assert.equal(s.state.disabled,true);}});
 check(name+' una configuración por carga, ninguna etiqueta extra',()=>{assert.equal(d.commands.filter(c=>c.kind==='config').length,d.tagLoads.length);assert(d.steps.every(s=>s.state.tagCount<=1&&s.state.allTagScripts.length<=1));assert(d.requests.every(r=>!(r.host==='www.googletagmanager.com'&&['/gtm.js','/gtag/js'].includes(r.path))));});
 check(name+' todo collect interceptado; sin lead ni formulario',()=>{assert(d.requests.every(r=>r.blocked));assert(d.requests.flatMap(r=>r.events).every(e=>e.destination==='G-WJ6METJRZD'&&!['generate_lead','form_start','form_submit'].includes(e.event)));assert(!d.requests.some(r=>r.host==='pyptecnologia.com'&&r.method==='POST'));});
}
for(const name of ['rpi-to-clg-router-history','history-back-rpi','history-forward-clg']){
 check('Duplicación demostrada '+name,()=>{const s=step(baseline,name);assert.equal(s.publicViews,1);assert.equal(s.networkViews.length,2);assert.equal(s.networkViews.filter(e=>e.originMarker==='app').length,1);assert.equal(s.networkViews.filter(e=>e.originMarker===null).length,1);assert.equal(new Set(s.networkViews.map(e=>e.eventSequence)).size,2);assert.equal(new Set(s.networkViews.map(e=>e.location)).size,1);});
 check('Marcador no causa duplicación '+name,()=>assert.equal(step(baseline,name,'baseline').networkViews.length,step(baseline,name).networkViews.length));
 check('Control offline solo historial desactivado elimina duplicación '+name,()=>{const s=step(control,name);assert.equal(s.publicViews,1);assert.equal(s.networkViews.length,1);assert.equal(s.networkViews[0].originMarker,'app');});
}
check('Enlace real RPI→Inicio duplica sin dos llamadas de aplicación',()=>{const s=step(uiAfter,'rpi-to-home-real-header');assert.equal(s.publicViews,1);assert.equal(s.networkViews.length,2);assert.equal(s.networkViews.filter(e=>e.originMarker==='app').length,1);});
for(const name of ['history-back-home-real-ui','history-forward-clg-real-ui'])check('Corrección BFCache '+name,()=>{assert.equal(step(uiBefore,name).publicViews,0);const s=step(uiAfter,name);assert.equal(s.publicViews,1);assert.equal(s.networkViews.length,1);assert.equal(s.tagLoads,0);assert.equal(s.configs,0);});
for(const name of ['accepted-home','initial-home-saved-consent','home-to-rpi-native-link','home-to-clg-real-card'])check('Vista inicial/documento único '+name,()=>{const s=step(uiAfter,name);assert.equal(s.publicViews,1);assert.equal(s.networkViews.length,1);});
const matrix=uiAfter.steps.map(s=>({scenario:s.name,app:s.publicViews,networkPageViews:s.networkViews.length,automatic:s.networkViews.filter(e=>e.originMarker===null).length,tagLoads:s.tagLoads,cookies:s.state.gaCookieCount}));
const result={date:'2026-10-20',passed:checks.filter(c=>c.ok).length,failed:checks.filter(c=>!c.ok).length,publicationReady:false,blocker:'Etiqueta pública ejecutada genera page_view adicional por historial. Corrección BFCache local verificada; corrección externa no realizada.',checks,matrix,externalCorrectionRequired:'Publicar configuración efectiva __ccd_em_page_view/historyEvents:false para G-WJ6METJRZD y repetir diagnóstico con etiqueta original sin modificar.',controlWarning:'El control cambia una copia local, no la propiedad GA4; no prueba corrección pública ni recepción de eventos.'};
fs.writeFileSync(base+'/diagnostico-consolidado.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({passed:result.passed,failed:result.failed,matrix},null,2));
if(result.failed)process.exitCode=1;

import fs from 'node:fs';
import {createHash} from 'node:crypto';
const records=[];
for(const url of ['https://www.googletagmanager.com/gtag/js?id=G-WJ6METJRZD','https://www.googletagmanager.com/gtag/js?id=G-WJ6METJRZD&pyp_final='+Date.now()]){
 const r=await fetch(url,{headers:{'Cache-Control':'no-cache','Pragma':'no-cache'},signal:AbortSignal.timeout(30000)}),bytes=Buffer.from(await r.arrayBuffer()),source=bytes.toString();
 const a=source.indexOf('"tags":')+7,b=source.indexOf('"predicates":',a),tags=JSON.parse(source.slice(a,b).trim().replace(/,$/,''));
 records.push({url,finalUrl:r.url,status:r.status,observedAt:new Date().toISOString(),sha256:createHash('sha256').update(bytes).digest('hex'),headers:Object.fromEntries([...r.headers].filter(([k])=>['date','age','cache-control','expires','etag','last-modified','content-type','vary','via'].includes(k))),destinationTags:tags.filter(t=>t.vtp_instanceDestinationId==='G-WJ6METJRZD'&&['__ccd_em_page_view','__ccd_em_form'].includes(t.function))});
}
fs.writeFileSync('docs/evidencias/PYP-035/ga4-publicacion-consulta-final.json',JSON.stringify({date:'2026-10-20',records},null,2)+'\n');
console.log(JSON.stringify(records.map(r=>({url:r.url,status:r.status,tags:r.destinationTags}))));

import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {spawn,execFileSync} from 'node:child_process';
const base='docs/evidencias/PYP-035', root=path.resolve(base,'build-temporal/comercial-diagnostico');
const ID='G-WJ6METJRZD', origin='https://pyptecnologia.com';
const suffix=process.argv[2]||'original';
const delay=ms=>new Promise(r=>setTimeout(r,ms));
const output={date:'2026-10-20',startedAt:new Date().toISOString(),suffix,downloads:[],steps:[],commands:[],requests:[],tagLoads:[],exceptions:[],checks:[]};
const publicUrl='https://www.googletagmanager.com/gtag/js?id='+ID;
// Controlled offline experiment: change ONLY destination historyEvents in the captured Google tag.
const observed=JSON.parse(fs.readFileSync(base+'/diagnostico-runtime-transporte204.json','utf8'));
output.downloads=observed.downloads;
const original=fs.readFileSync(path.resolve(base,'build-temporal/diagnostico/gtag-transporte204-1.js'));
if(createHash('sha256').update(original).digest('hex')!==observed.downloads[1].sha256)throw Error('Original snapshot hash mismatch');
const source=original.toString('utf8');
const pattern=/(\{"function":"__ccd_em_page_view"[^}]*"vtp_historyEvents":)true/g;
if([...source.matchAll(pattern)].length!==1)throw Error('Expected exactly one destination history setting');
const tag=Buffer.from(source.replace(pattern,'$1false'));
output.experiment={offlineOnly:true,sourceReport:'diagnostico-runtime-transporte204.json',originalHash:observed.downloads[1].sha256,executedHash:createHash('sha256').update(tag).digest('hex'),onlyChange:'__ccd_em_page_view/vtp_historyEvents:true → false',externalConfigurationChanged:false};
fs.writeFileSync(path.resolve(base,'build-temporal/diagnostico/gtag-control-historyoff.js'),tag);
const browser=spawn('C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',['--headless=new','--disable-gpu','--disable-extensions','--disable-background-networking','--no-first-run','--no-default-browser-check','--host-resolver-rules=MAP * 127.0.0.1','--remote-debugging-port=9387','--user-data-dir='+path.resolve(base,'browser-profile/diagnostico-'+suffix), 'about:blank'],{windowsHide:true,stdio:'ignore'});
let ws,seq=0,phase='setup',run='setup',mark=false,scriptId;
const pending=new Map();
const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;const timer=setTimeout(()=>{pending.delete(id);reject(Error('CDP timeout '+method));},15000);pending.set(id,{resolve,reject,timer});ws.send(JSON.stringify({id,method,params}));});
const instrument=marked=>`(()=>{let fn;Object.defineProperty(window,'gtag',{configurable:true,get(){return fn},set(value){if(typeof value!=='function'){fn=value;return;}fn=function(...args){const c={kind:args[0],name:typeof args[1]==='string'?args[1]:null,path:args[2]?.page_path||null,sendPageView:args[2]?.send_page_view,source:(new Error()).stack.split('\\n').slice(2,5).join(' | ')};window.__pypObserve(JSON.stringify(c));if(${marked}&&args[0]==='event'&&args[1]==='page_view')args[2]={...args[2],pyp_diagnostic_origin:'app'};return value.apply(this,args);};}});document.addEventListener('submit',e=>e.preventDefault(),true);})()`;
const parseCollect=(request,u)=>{
 const query=new URLSearchParams(u.search),lines=request.postData?request.postData.split(/\r?\n/):[''];
 const records=[];
 for(const line of lines){const params=new URLSearchParams(query);for(const [k,v]of new URLSearchParams(line))params.set(k,v);if(!params.get('en'))continue;
 records.push({event:params.get('en'),destination:params.get('tid'),location:(()=>{try{return new URL(params.get('dl')).pathname;}catch{return null;}})(),originMarker:params.get('ep.pyp_diagnostic_origin'),autoMarker:params.get('_ee'),eventSequence:params.get('_s'),parameterNames:[...params.keys()].filter(k=>!['cid','sid','sct','_p','_s','_ga','_gcl_au'].includes(k)).sort()});}
 return records;
};
try {
 let targets;
 for(let i=0;i<100;i++){try{targets=await(await fetch('http://127.0.0.1:9387/json/list',{signal:AbortSignal.timeout(500)})).json();break;}catch{await delay(100);}}
 if(!targets)throw Error('Edge CDP unavailable');
 ws=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
 ws.onmessage=event=>{
  const m=JSON.parse(event.data);
  if(m.id&&pending.has(m.id)){const p=pending.get(m.id);clearTimeout(p.timer);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result);return;}
  if(m.method==='Runtime.bindingCalled'){try{output.commands.push({run,phase,...JSON.parse(m.params.payload)});}catch{}}
  if(m.method==='Runtime.exceptionThrown')output.exceptions.push({run,phase,text:m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text});
  if(m.method==='Fetch.requestPaused')void(async()=>{
   const p=m.params,u=new URL(p.request.url),args={requestId:p.requestId};
   if(u.origin===origin&&['GET','HEAD'].includes(p.request.method)) {
    let file=path.join(root,decodeURIComponent(u.pathname));
    if(!file.startsWith(root+path.sep)&&file!==root)throw Error('Path outside artifact');
    if(fs.existsSync(file)&&fs.statSync(file).isDirectory())file=path.join(file,'index.html');
    if(!fs.existsSync(file))file=path.join(root,'index.html');
    const types={'.html':'text/html; charset=utf-8','.js':'text/javascript','.css':'text/css','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp','.svg':'image/svg+xml'};
