 if(forms.some(f=>!f.ok))throw Error('Formulario estático diferente');
 result={date:'2026-10-20',passed:true,indexTree:tree,sourceFilesCompared:source.length,sameSources:unchanged,endOfLineNormalized,forms,commands:commandResults,artifact:out,commitExecuted:false,pushExecuted:false,privacyGate:'Superada mediante etiqueta pública original: una vista por navegación y consentimiento correcto.'};
}catch(e){result={date:'2026-10-20',passed:false,indexTree:tree,commands:commandResults,error:e.message};process.exitCode=1;}
